// A new app's or artifact's address: generated by the server (GET /v1/names?kind=…), editable, checked as you type
// (GET /v1/names/:name). Same rules as server/deploys.ts validName.
import { useEffect, useRef, useState } from "react";
import { api, errorMessage, meta } from "../lib/api.ts";
import { Icon } from "./icons.tsx";

const NAME_RE = /^[a-z0-9](?:[a-z0-9-]{0,38}[a-z0-9])?$/;
/** A check's outcome; `retry`: it failed (network, 429), ask again. */
interface SlugCheck {
  name: string;
  ok: boolean;
  retry?: boolean;
}

export interface Slug {
  /** Fills in a fresh generated address (free when suggested). Typing meanwhile wins. */
  suggest(): Promise<SlugCheck>;
  /** The address once it's checked and free, else null (the field says why). */
  value(): Promise<string | null>;
  /** The field's props: <SlugField slug={…} />. */
  field: { input: React.RefObject<HTMLInputElement | null>; value: string; setValue: (v: string) => void; status: { state: string; text: string } };
}

/** The address picker's state; render it with <SlugField>. */
export function useSlug(kind: "app" | "page"): Slug {
  const input = useRef<HTMLInputElement>(null);
  const [value, setValueState] = useState("");
  const [status, setStatus] = useState({ state: "", text: "" });
  // `seq` counts edits: an answer for an older value is dropped. `last`: the latest check (or suggestion).
  const r = useRef({ seq: 0, timer: undefined as ReturnType<typeof setTimeout> | undefined, last: null as Promise<SlugCheck> | null, value: "" });
  const s = r.current;
  useEffect(() => () => clearTimeout(s.timer), [s]);

  const show = (state: string, text: string) => setStatus({ state, text });
  const settle = (my: number, name: string, ok: boolean, state: string, text: string): SlugCheck => {
    if (my === s.seq) show(state, text);
    return { name, ok };
  };
  const check = () => {
    clearTimeout(s.timer);
    const name = s.value, my = s.seq;
    if (!name) s.last = Promise.resolve(settle(my, name, false, "bad", "Enter an address."));
    else if (!NAME_RE.test(name) || name.includes("--")) {
      s.last = Promise.resolve(settle(my, name, false, "bad", "Use lowercase letters, numbers and single dashes, not at the start or end."));
    } else {
      show("", "Checking…");
      s.last = api<{ available: boolean; reason?: string; message?: string }>(`/v1/names/${encodeURIComponent(name)}`).then(
        (x) => x.available
          ? settle(my, name, true, "ok", `${name} is available`)
          : settle(my, name, false, "bad", x.reason === "taken" ? `${name} is taken. Try another.` : x.message ?? "Not a valid address."),
        (e) => ({ ...settle(my, name, false, "bad", `Couldn't check this address: ${errorMessage(e)}`), retry: true }),
      );
    }
    return s.last;
  };
  const setValue = (v: string) => {
    s.value = v;
    setValueState(v);
  };
  return {
    suggest() {
      const my = ++s.seq;
      clearTimeout(s.timer);
      show("", "Picking an address…");
      s.last = api<{ name: string }>(`/v1/names?kind=${kind}`).then(
        ({ name }) => {
          if (my !== s.seq) return { name, ok: false };
          setValue(name);
          return settle(my, name, true, "ok", `${name} is available`);
        },
        (e) => settle(my, "", false, "bad", `Couldn't pick an address: ${errorMessage(e)}`),
      );
      return s.last;
    },
    async value() {
      let x = s.last && (await s.last);
      if (!x || x.retry || x.name !== s.value) x = await check();
      return x.ok && x.name === s.value ? x.name : null;
    },
    field: {
      input,
      value,
      status,
      setValue(v: string) {
        setValue(v);
        s.seq++;
        s.last = null;
        show("", "");
        clearTimeout(s.timer);
        s.timer = setTimeout(check, 300);
      },
    },
  };
}

/** The address field: `<before><input><after>` (this server's app URL around the name), its status, its hint. */
export function SlugField({ slug, id, label = "Address", hint }: { slug: Slug; id: string; label?: string; hint: string }) {
  const { input, value, setValue, status } = slug.field;
  const [affix, setAffix] = useState<[string, string]>(["", ""]);
  useEffect(() => {
    let live = true;
    void meta().then((m) => {
      const [before = "", after = ""] = (m.appUrlTemplate ?? "").split("{name}");
      if (live) setAffix([before, after]);
    });
    return () => void (live = false);
  }, []);
  return (
    <div className="field slug-field">
      <label htmlFor={id}>{label}</label>
      <div className="slug-input" onMouseDown={(e) => {
        if (e.target !== input.current) {
          e.preventDefault();
          input.current?.focus();
        }
      }}>
        <span className="slug-affix js-slug-before" aria-hidden="true">{affix[0]}</span>
        <input
          className="input mono"
          id={id}
          ref={input}
          maxLength={40}
          spellCheck={false}
          autoComplete="off"
          autoCapitalize="off"
          aria-describedby={`${id}-status ${id}-hint`}
          aria-invalid={status.state === "bad" ? "true" : "false"}
          value={value}
          onChange={(e) => {
            // Lowercase as you type (subdomains are), keeping the caret where it was.
            const el = e.currentTarget, at = el.selectionStart;
            const lower = el.value.toLowerCase().replace(/[\s_]/g, "-");
            setValue(lower);
            if (lower !== el.value) requestAnimationFrame(() => el.setSelectionRange(at, at));
          }}
        />
        <span className="slug-affix js-slug-after" aria-hidden="true">{affix[1]}</span>
      </div>
      <p className="slug-status small" id={`${id}-status`} aria-live="polite" data-state={status.state}>
        {status.state === "ok" ? <Icon name="check" /> : status.state === "bad" ? <Icon name="x" /> : null}{status.text}
      </p>
      <p className="muted small" id={`${id}-hint`}>{hint}</p>
    </div>
  );
}
